using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SharkRuptureCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/SharkRuptureCustomDescription", order = 0)]
public class SharkRuptureCustomDescription : WhereXTimesCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SharkRuptureAction sharkRuptureAction = battleAction as SharkRuptureAction;
		return GetActionDescription(amountModified, battleAction, sharkRuptureAction.PurifyAction);
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		SharkRuptureAction sharkRuptureAction = battleAction as SharkRuptureAction;
		return Smart.Format(base.GetRawLocalizedDescription(battleAction), sharkRuptureAction.AdditionalTimesAmount);
	}
}
